    const productImportForm=`<form id="commerce-product-import" class="va-form va-import-form"><a class="va-template-download" href="/api/method/verityai_saas.api.commerce.download_product_template?workspace=${encodeURIComponent(workspace)}"><strong>Download Excel template</strong><span>Use the current workbook format for a reliable import.</span></a><div class="va-field full"><label>Completed Excel workbook</label><input type="file" name="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required></div><label class="va-check full"><input type="checkbox" name="update_existing"> Update products with matching item codes</label><div class="va-form-actions"><button type="button" class="va-button ghost" data-commerce-close>Cancel</button><button class="va-button">Import products</button></div></form>`;
    const erpnextForm=`<form id="commerce-erpnext" class="va-form"><div class="va-fields"><label class="va-check full"><input type="checkbox" name="enabled" ${erp.enabled?"checked":""}> Enable ERPNext connection</label>${field("ERPNext site URL","url",erp.url||"","url")}${field("Company","company",erp.company||"")}${field("Selling price list","selling_price_list",erp.selling_price_list||"Standard Selling")}${field("Customer group","customer_group",erp.customer_group||"All Customer Groups")}${field("Territory","territory",erp.territory||"All Territories")}${field("Sales taxes template","sales_taxes_template",erp.sales_taxes_template||"")}${field(`API key${erp.configured?" (configured)":""}`,"api_key","","password")}${field(`API secret${erp.configured?" (configured)":""}`,"api_secret","","password")}<label class="va-check full"><input type="checkbox" name="auto_sync_quotations" ${erp.auto_sync_quotations?"checked":""}> Sync approved quotations automatically</label><label class="va-check full"><input type="checkbox" name="assistant_connector_enabled" ${erp.assistant_connector_enabled?"checked":""}> Use the VerityAI ERPNext assistant connector</label></div><div class="va-form-actions"><button type="button" class="va-button ghost" data-commerce-close>Cancel</button>${erp.configured?'<button type="button" class="va-button secondary" id="erp-test-connection">Test connection</button>':""}<button class="va-button">Save connection</button></div></form>`;
    const quoteForm=`<form id="commerce-quote" class="va-form"><div class="va-fields"><div class="va-field full"><label>Customer</label><select name="customer" required><option value="">Choose customer</option>${customerOptions}</select></div>${field("Quotation date","transaction_date",new Date().toISOString().slice(0,10),"date")}${field("Valid until","valid_till","","date")}${field("Currency","currency","USD")}${field("Additional discount","discount_amount",0,"number")}${field("Tax rate %","tax_rate",0,"number")}${field("Notes","notes","","textarea",true)}</div><div class="va-subsection-heading"><div><h3>Line items</h3><p>Product selling prices are applied automatically. Override a line only when this quotation needs a special price.</p></div><button type="button" class="va-button ghost" id="add-quote-line">+ Add item</button></div><div id="quote-lines">${line()}</div><div class="va-form-actions"><button type="button" class="va-button ghost" data-commerce-close>Cancel</button><button class="va-button" ${customers.length&&products.length?"":"disabled"}>Save draft</button></div></form>`;
    content.innerHTML=`<div class="va-command-bar compact"><div><h2>Sales workspace</h2><p>Customers, products and quotations in one clean workflow.</p></div><div class="va-actions">${action("Add customer","customer")}${action("Import products","product-import")}${action("Add product","product")}${customers.length&&products.length?action("New quotation","quote","primary"):""}</div></div><div class="va-tabs" role="tablist">${[["overview","Overview"],["customers","Customers"],["products","Products"],["quotations","Quotations"]].map(([key,label])=>`<button type="button" role="tab" aria-selected="${commerceView===key}" class="${commerceView===key?"active":""}" data-commerce-view="${key}">${label}</button>`).join("")}</div><div class="va-commerce-view">${views[commerceView]||views.overview}</div><div class="va-drawer-backdrop" hidden><aside class="va-drawer" role="dialog" aria-modal="true">${drawer("customer","Customer details","Create or update a customer record.",customerForm)}${drawer("customer-detail","Customer","",'<div id="customer-detail-body"></div>')}${drawer("product","Product details","Manage the product or service and its selling price together.",productForm)}${drawer("product-import","Import products","Add or update your catalogue from an Excel workbook.",productImportForm)}${drawer("erpnext","ERPNext connection","Connect your ERPNext site and choose how catalogue and quotation data flows.",erpnextForm)}${drawer("quote","Create quotation","Prepare a customer proposal without leaving the Commerce workspace.",quoteForm)}</aside></div>`;
    const backdrop=document.querySelector(".va-drawer-backdrop");
    const closeDrawer=()=>{backdrop.hidden=true;document.body.classList.remove("va-no-scroll");backdrop.querySelector(".va-drawer")?.classList.remove("va-drawer-wide");backdrop.querySelectorAll("[data-commerce-panel]").forEach(panel=>panel.hidden=true);};
    document.querySelectorAll("[data-commerce-open]").forEach(button=>button.onclick=()=>{const panel=backdrop.querySelector(`[data-commerce-panel="${button.dataset.commerceOpen}"]`);const form=panel.querySelector("form");form?.reset();if(button.dataset.customerEdit){const customer=customers.find(row=>row.name===button.dataset.customerEdit);if(customer){form.customer.value=customer.name;["customer_name","customer_type","email","phone","tax_id","city","country","address","notes","status"].forEach(name=>{if(form[name])form[name].value=customer[name]??"";});}}if(button.dataset.productEdit){const product=products.find(row=>row.name===button.dataset.productEdit);if(product){form.product.value=product.name;["item_code","item_name","standard_rate","currency","stock_uom","item_group","description"].forEach(name=>{if(form[name])form[name].value=product[name]??"";});form.is_stock_item.checked=Boolean(product.is_stock_item);}}panel.hidden=false;backdrop.hidden=false;document.body.classList.add("va-no-scroll");window.setTimeout(()=>panel.querySelector('input:not([type="hidden"]), select, textarea')?.focus(),0);});
    document.querySelectorAll("[data-commerce-close]").forEach(button=>button.onclick=closeDrawer);
    backdrop.onclick=event=>{if(event.target===backdrop)closeDrawer();};
    document.onkeydown=event=>{if(event.key==="Escape"&&!backdrop.hidden)closeDrawer();};
    document.querySelectorAll("[data-commerce-view]").forEach(button=>button.onclick=()=>{commerceView=button.dataset.commerceView;commerce();});
    bind("commerce-customer",form=>{const values=json(form),customer=values.customer;delete values.customer;return call("verityai_saas.api.commerce.save_customer",{workspace,customer,values});},commerce);
    document.querySelectorAll("[data-customer-view]").forEach(button=>button.onclick=async()=>{button.disabled=true;try{const data=await call("verityai_saas.api.commerce.customer",{workspace,customer:button.dataset.customerView});const row=data.customer||{};const facts=[["Email",row.email],["Phone",row.phone],["Type",row.customer_type],["Status",row.status],["Tax ID",row.tax_id],["City",row.city],["Country",row.country],["Address",row.address],["Lifetime value",row.lifetime_value?`${row.currency||""} ${number(row.lifetime_value)}`:null],["Last contact",row.last_contact_on]];const panel=backdrop.querySelector('[data-commerce-panel="customer-detail"]');panel.querySelector("h2").textContent=row.customer_name||"Customer";panel.querySelector("#customer-detail-body").innerHTML=`<div class="va-detail-grid">${facts.filter(item=>item[1]).map(([label,value])=>`<div><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join("")}</div>${row.notes?`<div class="va-detail-block"><h3>Notes</h3><p>${esc(row.notes)}</p></div>`:""}<div class="va-detail-columns"><div><h3>Opportunities</h3>${(data.opportunities||[]).length?(data.opportunities||[]).map(item=>`<div class="va-detail-row"><strong>${esc(item.opportunity_name)}</strong>${pill(item.stage)}<span>${esc(item.currency)} ${number(item.amount)}</span></div>`).join(""):emptyState("No opportunities","")}</div><div><h3>Quotations</h3>${(data.quotations||[]).length?(data.quotations||[]).map(item=>`<div class="va-detail-row"><strong>${esc(item.name)}</strong>${pill(item.status)}<span>${esc(item.currency)} ${number(item.total)}</span></div>`).join(""):emptyState("No quotations","")}</div><div><h3>Appointments</h3>${(data.appointments||[]).length?(data.appointments||[]).map(item=>`<div class="va-detail-row"><strong>${esc(item.subject)}</strong>${pill(item.status)}<span>${esc(item.starts_on)}</span></div>`).join(""):emptyState("No appointments","")}</div><div><h3>Recent activity</h3>${(data.activities||[]).length?(data.activities||[]).map(item=>`<div class="va-detail-row"><strong>${esc(item.subject)}</strong>${pill(item.status)}<span>${esc(item.activity_type)}</span></div>`).join(""):emptyState("No activity","")}</div></div>`;panel.hidden=false;backdrop.querySelector(".va-drawer").classList.add("va-drawer-wide");backdrop.hidden=false;document.body.classList.add("va-no-scroll");}catch(err){alert(err.message,true);}finally{button.disabled=false;}});
    document.querySelectorAll("[data-delete-customer]").forEach(button=>button.onclick=async()=>{if(!window.confirm(`Delete “${button.dataset.customerTitle}”?`))return;button.disabled=true;try{await call("verityai_saas.api.commerce.delete_customer",{workspace,customer:button.dataset.deleteCustomer});alert("Customer deleted.");await commerce();}catch(err){alert(err.message,true);button.disabled=false;}});
    bind("commerce-product",form=>{const values={...json(form),active:1,is_stock_item:form.is_stock_item.checked?1:0};const product=values.product;delete values.product;return call("verityai_saas.api.commerce.save_product",{workspace,product,values});},commerce);
    document.querySelector("#commerce-erpnext")?.addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget;const button=event.submitter||form.querySelector('button:not([type="button"])');button.disabled=true;try{const values=json(form);values.enabled=form.enabled.checked?1:0;values.auto_sync_quotations=form.auto_sync_quotations.checked?1:0;values.assistant_connector_enabled=form.assistant_connector_enabled.checked?1:0;await call("verityai_saas.api.erpnext.update",{workspace,values});closeDrawer();alert("ERPNext connection saved.");await commerce();}catch(err){alert(err.message,true);button.disabled=false;}});
    document.querySelector("#erp-test-connection")?.addEventListener("click",async event=>{event.currentTarget.disabled=true;try{const result=await call("verityai_saas.api.erpnext.test",{workspace});alert(result.connector?`ERPNext and VerityAI connector are connected as ${result.user}.`:`ERPNext connected as ${result.user}.`);}catch(err){alert(err.message,true);}finally{event.currentTarget.disabled=false;}});
    document.querySelector("#erp-sync-products")?.addEventListener("click",async event=>{if(!window.confirm("Sync products and selling prices from ERPNext now?"))return;event.currentTarget.disabled=true;try{const result=await call("verityai_saas.api.erpnext.sync_products",{workspace});alert(`${number(result.created)} products added and ${number(result.updated)} updated.`);await commerce();}catch(err){alert(err.message,true);event.currentTarget.disabled=false;}});
    document.querySelector("#commerce-product-import")?.addEventListener("submit",async event=>{
      event.preventDefault();
      const form=event.currentTarget;const button=event.submitter||form.querySelector('button:not([type="button"])');const file=form.file.files[0];
      if(!file)return;
      button.disabled=true;button.classList.add("loading");
      const body=new FormData();body.append("workspace",workspace);body.append("update_existing",form.update_existing.checked?"1":"0");body.append("file",file);
      try{
        const response=await fetch("/api/method/verityai_saas.api.commerce.import_products",{method:"POST",headers:{"X-Frappe-CSRF-Token":window.csrf_token||""},body});
        const payload=await response.json();const result=payload.message||payload;
        if(!response.ok||!result.success)throw new Error(result.error||"Product import failed.");
        const imported=result.data;closeDrawer();alert(`${number(imported.created)} created, ${number(imported.updated)} updated, ${number(imported.skipped)} skipped.`);await commerce();
      }catch(err){alert(err.message,true);button.disabled=false;button.classList.remove("loading");}
    });
    const lines=document.querySelector("#quote-lines");
    const bindLineRemoval=()=>document.querySelectorAll("[data-remove-line]").forEach(button=>button.onclick=()=>{if(document.querySelectorAll(".va-quote-line").length>1)button.closest(".va-quote-line").remove();});
    bindLineRemoval(); document.querySelector("#add-quote-line").onclick=()=>{lines.insertAdjacentHTML("beforeend",line());bindLineRemoval();};
    document.querySelector("#commerce-quote").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget;const button=form.querySelector('button[type="submit"],button:not([type])');button.disabled=true;try{const values=json(form);values.items=[...form.querySelectorAll(".va-quote-line")].map(row=>({product:row.querySelector('[name="product"]').value,qty:row.querySelector('[name="qty"]').value,rate:row.querySelector('[name="rate"]').value,discount_percent:row.querySelector('[name="discount_percent"]').value}));await call("verityai_saas.api.commerce.save_quotation",{workspace,values});alert("Quotation draft created.");await commerce();}catch(err){alert(err.message,true);button.disabled=false;}});
